// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests

const express = require('express');
const app = express();

// Configuration from environment variables with safe defaults
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '127.0.0.1'; // Bind to localhost by default for security
const NODE_ENV = process.env.NODE_ENV || 'development';
const HEALTH_STATUS = process.env.HEALTH_STATUS || 'ok';
const API_PREFIX = process.env.API_PREFIX || '';

app.get(`${API_PREFIX}/health`, (req, res) => {
  res.json({ 
    status: HEALTH_STATUS, 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get(`${API_PREFIX}/users`, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Only listen if not running in test mode (useful for testing frameworks)
if (NODE_ENV !== 'test') {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT} in ${NODE_ENV} mode`);
  });
}

module.exports = app;

